{
  "name": "Zaber 菊花链式电动位移台与光学外设系统",
  "name_en": "Zaber daisy-chained motorized stage and optical peripheral system",
  "manufacturer": "Zaber",
  "description": "这是一类通过串口菊花链连接的 Zaber 实验室自动化设备系统，可包含电动位移台、滤光轮或滤块转塔，以及 LED 光源控制器。它常用于显微镜和光学实验中，实现样品定位、滤光片切换和照明控制等自动化操作。",
  "description_en": "This is a family of Zaber laboratory automation devices connected over a serial daisy chain, including motorized stages, filter wheels or filter cube turrets, and LED light controllers. It is commonly used in microscopy and optical experiments for automated sample positioning, filter switching, and illumination control.",
  "tag_hints": [
    "motorized stage",
    "filter wheel",
    "LED illumination control",
    "serial daisy chain",
    "microscopy automation",
    "optomechanics"
  ],
  "actions": [
    {
      "action_name": "auto-lock",
      "description": "锁定与设备菊花链的串口连接，避免通信冲突。",
      "description_en": "Lock the serial connection to the device daisy chain to avoid communication conflicts."
    },
    {
      "action_name": "auto-write",
      "description": "向设备的串口链路写入控制命令或数据。",
      "description_en": "Write control commands or data to the device serial link."
    },
    {
      "action_name": "auto-readline",
      "description": "从设备的串口链路读取一行返回信息。",
      "description_en": "Read one line of response from the device serial link."
    }
  ]
}

